package com.flashplay.android

import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONArray
import org.json.JSONObject
import java.io.BufferedReader
import java.io.OutputStreamWriter
import java.net.HttpURLConnection
import java.net.URL

class MiniMaxGenerator {
    suspend fun generate(
        gameName: String,
        prompt: String,
        style: RenderStyle
    ): GeneratedHtmlGame = withContext(Dispatchers.IO) {
        val apiKey = BuildConfig.MINIMAX_API_KEY.trim()
        if (apiKey.isBlank()) {
            throw IllegalStateException("MINIMAX_API_KEY is missing. Add it to android/local.properties or your shell environment.")
        }

        val endpoint = BuildConfig.MINIMAX_BASE_URL.trimEnd('/') + BuildConfig.MINIMAX_PATH
        val requestBody = JSONObject().apply {
            put("model", BuildConfig.MINIMAX_MODEL)
            put("temperature", 1)
            put(
                "messages",
                JSONArray()
                    .put(
                        JSONObject().apply {
                            put("role", "system")
                            put("name", "FlashPlayAndroid")
                            put("content", buildSystemPrompt(style))
                        }
                    )
                    .put(
                        JSONObject().apply {
                            put("role", "user")
                            put("name", "user")
                            put("content", buildUserPrompt(gameName, prompt, style))
                        }
                    )
            )
        }

        val connection = (URL(endpoint).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            connectTimeout = 150_000
            readTimeout = 150_000
            doInput = true
            doOutput = true
            setRequestProperty("Content-Type", "application/json")
            setRequestProperty("Authorization", "Bearer $apiKey")
        }

        try {
            OutputStreamWriter(connection.outputStream, Charsets.UTF_8).use { writer ->
                writer.write(requestBody.toString())
            }

            val statusCode = connection.responseCode
            val raw = readText(
                if (statusCode in 200..299) connection.inputStream else connection.errorStream
            )

            if (statusCode !in 200..299) {
                throw IllegalStateException("MiniMax request failed ($statusCode): $raw")
            }

            val root = JSONObject(raw)
            val text = extractText(root).trim()
            if (text.isBlank()) {
                throw IllegalStateException("MiniMax returned empty content.")
            }
            return@withContext parseGeneratedJson(text)
        } finally {
            connection.disconnect()
        }
    }

    private fun buildSystemPrompt(style: RenderStyle): String {
        val routePrompt = when (style) {
            RenderStyle.TwoD -> "game-engine: build a stable 2D mobile mini game with tap, avoid, collect, puzzle or relaxing loops."
            RenderStyle.ThreeD -> "build-game: build a lightweight 3D mobile demo with stronger visual depth but still easy to run in a mobile WebView."
        }
        return listOf(
            "You are FlashPlay Android's mini game generator.",
            "Route: $routePrompt",
            "Return strict JSON only.",
            "No markdown. No code fences. No extra explanation.",
            "Only three top-level fields are allowed: title, summary, html.",
            "title must be a concise English game name.",
            "summary must be one English sentence for the player.",
            "html must be a full standalone index.html that runs in Android WebView.",
            "The game must support touch and mouse input.",
            "Use inline CSS and JS only; do not import external assets.",
            "The game must fit portrait mobile screens and fill the full viewport.",
            "Keep the game simple, playable, and visually clean."
        ).joinToString("\n")
    }

    private fun buildUserPrompt(gameName: String, prompt: String, style: RenderStyle): String {
        return listOf(
            "Game name: $gameName",
            "Idea: $prompt",
            "Style: ${style.label}",
            "",
            "Build a mobile web mini game now."
        ).joinToString("\n")
    }

    private fun extractText(root: JSONObject): String {
        val choices = root.optJSONArray("choices") ?: return ""
        for (i in 0 until choices.length()) {
            val choice = choices.optJSONObject(i) ?: continue
            val message = choice.optJSONObject("message")
            val content = message?.opt("content")
            when (content) {
                is String -> if (content.isNotBlank()) return content
                is JSONArray -> {
                    val joined = buildString {
                        for (j in 0 until content.length()) {
                            val item = content.opt(j)
                            when (item) {
                                is String -> append(item)
                                is JSONObject -> append(item.optString("text"))
                            }
                        }
                    }
                    if (joined.isNotBlank()) return joined
                }
            }
        }
        return root.optString("reply")
    }

    private fun parseGeneratedJson(raw: String): GeneratedHtmlGame {
        val clean = raw
            .removePrefix("```json")
            .removePrefix("```")
            .removeSuffix("```")
            .trim()

        val start = clean.indexOf('{')
        val end = clean.lastIndexOf('}')
        if (start < 0 || end <= start) {
            Log.e("MiniMaxGenerator", "Invalid JSON payload: $clean")
            throw IllegalStateException("MiniMax returned invalid JSON.")
        }
        val json = JSONObject(clean.substring(start, end + 1))
        val title = json.optString("title").ifBlank { "FlashPlay Game" }
        val summary = json.optString("summary").ifBlank { "A generated mini game for FlashPlay Android." }
        val html = json.optString("html").ifBlank { buildFallbackHtml(title, summary) }
        return GeneratedHtmlGame(title = title, summary = summary, html = html)
    }

    private fun readText(stream: java.io.InputStream?): String {
        if (stream == null) return ""
        return BufferedReader(stream.reader(Charsets.UTF_8)).use { it.readText() }
    }

    private fun buildFallbackHtml(title: String, summary: String): String {
        return """
            <!doctype html>
            <html>
            <head>
              <meta charset="utf-8" />
              <meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover" />
              <style>
                html,body{margin:0;height:100%;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;background:#111;color:#fff}
                body{display:flex;align-items:center;justify-content:center}
                main{padding:24px;text-align:center}
                h1{margin:0 0 12px;font-size:28px}
                p{margin:0;opacity:.8;line-height:1.5}
              </style>
            </head>
            <body>
              <main>
                <h1>${escapeHtml(title)}</h1>
                <p>${escapeHtml(summary)}</p>
              </main>
            </body>
            </html>
        """.trimIndent()
    }

    private fun escapeHtml(value: String): String = value
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("\"", "&quot;")
}

