    var lastGeneratedGameUrl by mutableStateOf<String?>(null)
        private set
    var activeGame by mutableStateOf<FlashGame?>(null)
    var pendingPlayGameId by mutableStateOf<String?>(null)
        private set

    fun switchTab(tab: FlashTab) {
        selectedTab = tab
    }

    fun openGame(game: FlashGame) {
        pendingPlayGameId = game.id
        selectedTab = FlashTab.Home
    }

    fun closeGame() {
        activeGame = null
    }

    fun consumePendingPlayGameId() {
        pendingPlayGameId = null
    }

    fun updateName(value: String) {
        gameName = value
    }

    fun updatePrompt(value: String) {
        gamePrompt = value
    }

    fun updateStyle(value: RenderStyle) {
        renderStyle = value
    }

    fun toggleFavorite(gameId: String) {
        feedGames = feedGames.map { game ->
            if (game.id == gameId) game.copy(isFavorite = !game.isFavorite) else game
        }
        generatedGames = generatedGames.map { game ->
            if (game.id == gameId) game.copy(isFavorite = !game.isFavorite) else game
        }
        favoriteGames = (feedGames + generatedGames).filter { it.isFavorite }.distinctBy { it.id }
    }

    fun generateGame() {
        if (isGenerating) return
        val cleanName = gameName.trim()
        val cleanPrompt = gamePrompt.trim()
        if (cleanName.isEmpty() || cleanPrompt.isEmpty()) {
            generationError = "Please enter both the game name and gameplay description."
            return
        }

        isGenerating = true
        generationError = null
        lastGeneratedGameUrl = null

        viewModelScope.launch {
            try {
                val result = generator.generate(
                    gameName = cleanName,
                    prompt = cleanPrompt,
                    style = renderStyle
                )
                val published = publisher.publish(
                    gameName = cleanName,
                    generated = result
                )
                val game = FlashGame(
                    title = result.title,
                    summary = result.summary,
                    style = renderStyle,
                    source = GameSource.ExternalUrl(published.gameUrl),
                    palette = FlashPlayPalette.Cards[(generatedGames.size + 1) % FlashPlayPalette.Cards.size],
                    creator = "aigames",
                    isGenerated = true
                )
                lastGeneratedGameUrl = published.gameUrl
                generatedGames = listOf(game) + generatedGames
                feedGames = listOf(game) + feedGames
                pendingPlayGameId = game.id
                selectedTab = FlashTab.Home
            } catch (error: Throwable) {
                generationError = error.message ?: "Failed to generate game."
            } finally {
                isGenerating = false
            }
        }
    }
