@SuppressLint("SetJavaScriptEnabled")
@Composable
private fun GameWebSurface(
    game: FlashGame,
    modifier: Modifier = Modifier
) {
    val context = LocalContext.current
    AndroidView(
        modifier = modifier.background(game.palette.primary),
        factory = {
            WebView(context).apply {
                layoutParams = android.view.ViewGroup.LayoutParams(
                    android.view.ViewGroup.LayoutParams.MATCH_PARENT,
                    android.view.ViewGroup.LayoutParams.MATCH_PARENT
                )
                webViewClient = object : WebViewClient() {
                    override fun onPageFinished(view: WebView, url: String?) {
                        view.evaluateJavascript(FLASHPLAY_WEBVIEW_BRIDGE, null)
                    }
                }
                webChromeClient = WebChromeClient()
                settings.javaScriptEnabled = true
                settings.domStorageEnabled = true
                settings.cacheMode = WebSettings.LOAD_DEFAULT
                settings.useWideViewPort = true
                settings.loadWithOverviewMode = true
                settings.mediaPlaybackRequiresUserGesture = false
                overScrollMode = WebView.OVER_SCROLL_NEVER
                setBackgroundColor(android.graphics.Color.TRANSPARENT)
            }
        },
        update = { webView ->
            if (webView.tag != game.id) {
                webView.tag = game.id
                when (val source = game.source) {
                    is GameSource.ExternalUrl -> webView.loadUrl(source.url)
                    is GameSource.LocalHtml -> webView.loadDataWithBaseURL(
                        "https://flashplay.local/",
                        source.html,
                        "text/html",
                        "utf-8",
                        null
                    )
                }
            }
        }
    )
}

private fun FlashGame.displayTitle(): String {
    val raw = title.trim()
    if (raw.isBlank()) return "Untitled"
    val afterChineseName = raw.substringAfter("游戏名：", raw)
    return afterChineseName
        .substringBefore("玩法：")
        .substringBefore("。")
        .substringBefore("\n")
        .trim()
        .ifBlank { raw }
}

private fun FlashGame.shareUrl(): String {
    val sourceUrl = (source as? GameSource.ExternalUrl)?.url ?: return "Generated locally in FlashPlay Android"
    if (sourceUrl.contains("thenext.games/game/")) {
        val slug = sourceUrl.substringAfterLast("/").substringBefore("?")
        if (slug.isNotBlank()) {
            return "https://github.com/brianclan/aigames/tree/main/$slug"
        }
    }
    val marker = "cdn.jsdelivr.net/gh/"
    if (sourceUrl.contains(marker)) {
        val tail = sourceUrl.substringAfter(marker)
        val parts = tail.split("/")
        if (parts.size >= 3) {
            val ownerRepo = parts[0].substringBefore("@")
            val slug = parts[1]
            return "https://github.com/$ownerRepo/tree/main/$slug"
        }
    }
    return sourceUrl
}

