private fun FlashGame.displayTitle(): String {
    val raw = title.trim()
    if (raw.isBlank()) return "Untitled"
    val afterChineseName = raw.substringAfter("游戏名：", raw)
    return afterChineseName
        .substringBefore("玩法：")
        .substringBefore("。")
        .substringBefore("\n")
        .trim()
        .ifBlank { raw }
}

private fun FlashGame.shareUrl(): String {
    val sourceUrl = (source as? GameSource.ExternalUrl)?.url ?: return "Generated locally in FlashPlay Android"
    if (sourceUrl.contains("thenext.games/game/")) {
        val slug = sourceUrl.substringAfterLast("/").substringBefore("?")
        if (slug.isNotBlank()) {
            return "https://github.com/brianclan/aigames/tree/main/$slug"
        }
    }
    val marker = "cdn.jsdelivr.net/gh/"
    if (sourceUrl.contains(marker)) {
        val tail = sourceUrl.substringAfter(marker)
        val parts = tail.split("/")
        if (parts.size >= 3) {
            val ownerRepo = parts[0].substringBefore("@")
            val slug = parts[1]
            return "https://github.com/$ownerRepo/tree/main/$slug"
        }
    }
    return sourceUrl
}

