package com.flashplay.android

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.io.ByteArrayOutputStream
import java.net.HttpURLConnection
import java.net.URL

class AIGamesPublisher {
    suspend fun publish(gameName: String, generated: GeneratedHtmlGame): PublishedGame =
        withContext(Dispatchers.IO) {
            val slug = slugify(gameName.ifBlank { generated.title })
            uploadFile(
                endpoint = BuildConfig.AIGAMES_CONFIG_ENDPOINT,
                gameFolder = slug,
                fileName = "config.json",
                mimeType = "application/json",
                fileData = """{"title":${JSONObject.quote(generated.title)}}""".toByteArray(Charsets.UTF_8)
            )
            val indexPayload = uploadFile(
                endpoint = BuildConfig.AIGAMES_INDEX_ENDPOINT,
                gameFolder = slug,
                fileName = "index.html",
                mimeType = "text/html",
                fileData = generated.html.toByteArray(Charsets.UTF_8)
            )
            uploadFile(
                endpoint = BuildConfig.AIGAMES_PREVIEW_ENDPOINT,
                gameFolder = slug,
                fileName = "preview.png",
                mimeType = "image/png",
                fileData = PREVIEW_PNG
            )

            PublishedGame(
                slug = slug,
                gameUrl = "${BuildConfig.AIGAMES_PUBLIC_GAME_BASE_URL.trimEnd('/')}/$slug",
                rawUrl = indexPayload.optJSONObject("data")?.optString("downloadUrl")
                    ?.ifBlank { indexPayload.optJSONObject("data")?.optString("htmlUrl") }
            )
        }

    private fun uploadFile(
        endpoint: String,
        gameFolder: String,
        fileName: String,
        mimeType: String,
        fileData: ByteArray
    ): JSONObject {
        val boundary = "FlashPlayAndroid${System.currentTimeMillis()}"
        val body = ByteArrayOutputStream().apply {
            writeText("--$boundary\r\n")
            writeText("Content-Disposition: form-data; name=\"gameFolder\"\r\n\r\n")
            writeText(gameFolder)
            writeText("\r\n")
            writeText("--$boundary\r\n")
            writeText("Content-Disposition: form-data; name=\"file\"; filename=\"$fileName\"\r\n")
            writeText("Content-Type: $mimeType\r\n\r\n")
            write(fileData)
            writeText("\r\n--$boundary--\r\n")
        }.toByteArray()

        val connection = (URL(endpoint).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            connectTimeout = 45_000
            readTimeout = 45_000
            doInput = true
            doOutput = true
            setRequestProperty("Content-Type", "multipart/form-data; boundary=$boundary")
            setRequestProperty("Content-Length", body.size.toString())
        }

        try {
            connection.outputStream.use { it.write(body) }
            val statusCode = connection.responseCode
            val responseText = (
                if (statusCode in 200..299) connection.inputStream else connection.errorStream
            )?.bufferedReader(Charsets.UTF_8)?.use { it.readText() }.orEmpty()
            if (statusCode !in 200..299) {
                throw IllegalStateException("aigames upload failed ($statusCode): $responseText")
            }

            val payload = JSONObject(responseText)
            if (payload.optInt("code") != 200) {
                throw IllegalStateException("aigames upload invalid: ${payload.optString("code", "unknown")}")
            }
            return payload
        } finally {
            connection.disconnect()
        }
    }

    private fun ByteArrayOutputStream.writeText(value: String) {
        write(value.toByteArray(Charsets.UTF_8))
    }

    private fun slugify(value: String): String {
        val base = value
            .lowercase()
            .replace(Regex("[^a-z0-9]+"), "-")
            .trim('-')
            .take(30)
            .ifBlank { "flashplay-game" }
        return "$base-${System.currentTimeMillis()}"
    }

    private companion object {
        val PREVIEW_PNG: ByteArray = android.util.Base64.decode(
            "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO9W8j8AAAAASUVORK5CYII=",
            android.util.Base64.DEFAULT
        )
    }
}

