private fun LabelPill(text: String) {
    Box(
        modifier = Modifier
            .clip(RoundedCornerShape(14.dp))
            .background(Color.White.copy(alpha = 0.7f))
            .padding(horizontal = 9.dp, vertical = 5.dp),
