import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONArray
import org.json.JSONObject
import java.io.BufferedReader
import java.io.OutputStreamWriter
import java.net.HttpURLConnection
import java.net.URL

class AgentChatClient {
    suspend fun reply(history: List<AgentMessage>, userText: String, insight: EmotionInsight): String =
        withContext(Dispatchers.IO) {
            val apiKey = BuildConfig.MINIMAX_API_KEY.trim()
            if (apiKey.isBlank()) return@withContext fallbackReply(insight)

            val endpoint = "https://api.minimax.io/v1/text/chatcompletion_v2"
            val messages = JSONArray().apply {
                put(
                    JSONObject().apply {
                        put("role", "system")
                        put("name", "MuseAgent")
                        put(
                            "content",
                            "You are a warm cartoon music companion inside a music app. Reply in 1-2 short sentences. You help the user name emotions and turn them into music ideas. Do not mention APIs, models, or vendors."
                        )
                    }
                )
                history.takeLast(8).forEach { message ->
                    put(
                        JSONObject().apply {
                            put("role", if (message.fromUser) "user" else "assistant")
                            put("name", if (message.fromUser) "user" else "MuseAgent")
                            put("content", message.text)
                        }
                    )
                }
                put(
                    JSONObject().apply {
                        put("role", "user")
                        put("name", "user")
                        put("content", "$userText\nMood=${insight.mood}, Energy=${insight.energy}, Direction=${insight.musicDirection}")
                    }
                )
            }
            val body = JSONObject().apply {
                put("model", "MiniMax-M2.7")
                put("temperature", 0.9)
                put("messages", messages)
            }

            val connection = (URL(endpoint).openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                connectTimeout = 60_000
                readTimeout = 90_000
                doInput = true
                doOutput = true
                setRequestProperty("Content-Type", "application/json")
                setRequestProperty("Authorization", "Bearer $apiKey")
            }

            try {
                OutputStreamWriter(connection.outputStream, Charsets.UTF_8).use { it.write(body.toString()) }
                val code = connection.responseCode
                val raw = readText(if (code in 200..299) connection.inputStream else connection.errorStream)
                if (code !in 200..299) return@withContext fallbackReply(insight)
                val root = JSONObject(raw)
                extractText(root).ifBlank { fallbackReply(insight) }
            } finally {
                connection.disconnect()
            }
        }

    private fun extractText(root: JSONObject): String {
        val choices = root.optJSONArray("choices") ?: return root.optString("reply")
        for (index in 0 until choices.length()) {
            val message = choices.optJSONObject(index)?.optJSONObject("message") ?: continue
            val content = message.opt("content")
            if (content is String && content.isNotBlank()) return content.trim()
            if (content is JSONArray) {
                val text = buildString {
                    for (itemIndex in 0 until content.length()) {
                        val item = content.opt(itemIndex)
                        if (item is JSONObject) append(item.optString("text"))
                        if (item is String) append(item)
                    }
                }.trim()
                if (text.isNotBlank()) return text
            }
        }
        return ""
    }

    private fun fallbackReply(insight: EmotionInsight): String {
        return "I feel a ${insight.mood.lowercase()} color in this. I can shape it into ${insight.musicDirection.lowercase()} and keep the energy ${insight.energy.lowercase()}."
    }

    private fun readText(stream: java.io.InputStream?): String {
        if (stream == null) return ""
        return BufferedReader(stream.reader(Charsets.UTF_8)).use { it.readText() }
    }
}

