    var selectedTab by mutableStateOf(FlashTab.Home)
        private set

    var feedTracks by mutableStateOf(loadLibrary())
        private set

    var generatedTracks by mutableStateOf(feedTracks.filter { it.isGenerated })
        private set

    var favoriteTracks by mutableStateOf(feedTracks.filter { it.isFavorite })
        private set

