        private set
    var agentExpression by mutableStateOf("calm")
        private set
    var emotionInsight by mutableStateOf(
        EmotionInsight(
            mood = "Open",
            energy = "Medium",
            musicDirection = "Start a conversation with your music agent."
        )
    )
        private set
    var agentMessages by mutableStateOf(loadAgentHistory())
        private set
    var recommendations by mutableStateOf(
