    fun clearAgentHistory() {
        agentMessages = listOf(
            AgentMessage(
                text = "Fresh page. Tell me what mood you want to turn into music.",
                fromUser = false,
                expression = "happy"
            )
        )
        agentExpression = "calm"
        saveAgentHistory()
    }

    fun useRecommendation(recommendation: MusicRecommendation) {
        trackTitle = recommendation.title
        musicPrompt = recommendation.prompt
        lyrics = defaultSongLyrics(recommendation.title)
        musicMode = MusicMode.Instrumental
        selectedTab = FlashTab.Create
    }

    fun sendAgentMessage() {
        val clean = agentInput.trim()
        if (clean.isEmpty() || isAgentThinking) return
        agentInput = ""
        val insight = analyzeEmotion(clean)
        emotionInsight = insight
        agentExpression = expressionFor(insight)
        val generatedRecommendations = buildRecommendations(insight, clean)
        recommendations = generatedRecommendations
        agentMessages = agentMessages + AgentMessage(clean, fromUser = true, mood = insight.mood, expression = "listening")
        saveAgentHistory()
        isAgentThinking = true
        viewModelScope.launch {
            try {
                val reply = chatClient.reply(agentMessages, clean, insight)
                agentMessages = agentMessages + AgentMessage(
                    text = reply,
                    fromUser = false,
                    mood = insight.mood,
                    expression = agentExpression
                )
                saveAgentHistory()
            } finally {
                isAgentThinking = false
            }
        }
    }

    fun toggleFavorite(trackId: String) {
        feedTracks = feedTracks.map { track ->
            if (track.id == trackId) track.copy(isFavorite = !track.isFavorite) else track
        }
        generatedTracks = generatedTracks.map { track ->
            if (track.id == trackId) track.copy(isFavorite = !track.isFavorite) else track
        }
        favoriteTracks = (feedTracks + generatedTracks).filter { it.isFavorite }.distinctBy { it.id }
        saveLibrary()
    }

    fun generateMusic() {
        if (isGenerating) return
        val cleanTitle = trackTitle.trim()
        val cleanPrompt = musicPrompt.trim()
        if (cleanTitle.isEmpty() || cleanPrompt.isEmpty()) {
            generationError = "Please enter both the track title and music prompt."
            return
        }

        isGenerating = true
        generationError = null
        lastGeneratedAudioUrl = null

        viewModelScope.launch {
            try {
                val result = generator.generate(
                    title = cleanTitle,
                    prompt = cleanPrompt,
                    lyrics = lyrics.trim().ifBlank { defaultSongLyrics(cleanTitle) },
                    mode = musicMode
                )
                val track = MusicTrack(
                    title = result.title,
                    summary = result.summary,
                    prompt = result.prompt,
                    audioUrl = result.audioUrl,
                    localPath = result.localPath,
                    durationMs = result.durationMs,
                    mode = result.mode,
                    palette = FlashPlayPalette.Cards[(generatedTracks.size + 1) % FlashPlayPalette.Cards.size],
                    creator = "Local",
                    isGenerated = true
                )
                lastGeneratedAudioUrl = result.audioUrl
                generatedTracks = listOf(track) + generatedTracks
                feedTracks = listOf(track) + feedTracks
                dailyVibe = "Latest: ${track.title} - ${track.durationMs?.div(1000) ?: "ready"}s saved locally."
                pendingPlayTrackId = track.id
