private fun loadSeedLibrary(): List<MusicTrack> {
    val app = getApplication<Application>()
    return runCatching {
        val manifestText = app.assets.open("seed_music/manifest.json")
            .bufferedReader(Charsets.UTF_8)
            .use { it.readText() }
        val array = JSONArray(manifestText)
        val seedDir = File(app.filesDir, "seed_music").apply { mkdirs() }
        buildList {
            for (index in 0 until array.length()) {
                val item = array.optJSONObject(index) ?: continue
                val assetFile = item.optString("file")
                val output = File(seedDir, assetFile.substringAfterLast("/"))
                if (!output.exists()) {
                    app.assets.open(assetFile).use { input ->
                        output.outputStream().use { fileOut -> input.copyTo(fileOut) }
                    }
                }
                val mode = runCatching { MusicMode.valueOf(item.optString("mode")) }.getOrDefault(MusicMode.Instrumental)
                add(
                    MusicTrack(
                        title = item.optString("title", "Seed Track"),
                        summary = "${mode.label} saved in your starter feed.",
                        prompt = item.optString("prompt"),
                        audioUrl = "",
                        localPath = output.absolutePath,
                        durationMs = item.optLong("durationMs").takeIf { !item.isNull("durationMs") && it > 0 },
                        mode = mode,
                        palette = FlashPlayPalette.Cards[index % FlashPlayPalette.Cards.size],
                        creator = "Local",
                        isGenerated = false
                    )
                )
            }
        }.also {
            if (it.isNotEmpty()) {
                val persist = JSONArray()
                it.forEach { track -> persist.put(track.toJson()) }
                libraryFile.writeText(persist.toString())
            }
        }
    }.getOrDefault(emptyList())
}

