                    onValueChange = store::updateLyrics,
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(210.dp),
                    label = { Text("Lyrics for Song mode") },
                    minLines = 6,
                    shape = RoundedCornerShape(18.dp)
                )
            }
