@Composable
private fun MusicCanvasAnimation(
    track: MusicTrack,
    visualIndex: Int,
    isPlaying: Boolean,
    modifier: Modifier = Modifier
) {
    val infinite = rememberInfiniteTransition(label = "feed-visual")
    val phase by infinite.animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(animation = tween(1400), repeatMode = RepeatMode.Restart),
        label = "visual-phase"
    )
    val idlePhase by animateFloatAsState(
        targetValue = if (isPlaying) phase else 0.18f,
        animationSpec = tween(220),
        label = "visual-idle"
    )
    val colors = remember(track.id) {
        listOf(track.palette.accent, FlashPlayPalette.Warm, FlashPlayPalette.Ink.copy(alpha = 0.72f))
    }
    Canvas(modifier = modifier.padding(18.dp)) {
        val p = idlePhase
        val center = Offset(size.width / 2f, size.height / 2f)
        when (visualIndex) {
            0, 5 -> {
                val bars = 7
                val gap = size.width / (bars + 2)
                for (i in 0 until bars) {
                    val wave = kotlin.math.sin(((p * 360f) + i * 38f) * Math.PI / 180f).toFloat()
                    val h = size.height * (0.22f + 0.46f * ((wave + 1f) / 2f))
                    val w = 12.dp.toPx()
                    val x = gap * (i + 1)
                    drawRoundRect(
                        color = colors[i % colors.size],
                        topLeft = Offset(x - w / 2f, center.y - h / 2f),
                        size = Size(w, h),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(w, w)
                    )
                }
            }
            1, 2 -> {
                for (i in 0..2) {
                    val radius = size.minDimension * (0.18f + i * 0.13f + p * 0.08f)
                    drawCircle(
                        color = colors[i].copy(alpha = 0.22f + i * 0.14f),
                        radius = radius,
                        center = center,
                        style = Stroke(width = 5.dp.toPx())
                    )
                }
                drawCircle(colors[1], radius = 22.dp.toPx(), center = center)
            }
            else -> {
                for (i in 0 until 9) {
                    val angle = ((i * 40f) + p * 360f) * Math.PI / 180f
                    val radius = size.minDimension * (0.14f + (i % 3) * 0.11f)
                    val x = center.x + kotlin.math.cos(angle).toFloat() * radius
                    val y = center.y + kotlin.math.sin(angle).toFloat() * radius
                    drawCircle(colors[i % colors.size], radius = (7 + (i % 3) * 3).dp.toPx(), center = Offset(x, y))
                }
            }
        }
    }
}

private fun lottieAssetFor(track: MusicTrack): String {
    val assets = listOf(
        "lottie_music/equalizer_neon.json",
