@Composable
private fun MusicCanvasAnimation(
    track: MusicTrack,
    visualIndex: Int,
    isPlaying: Boolean,
    tempo: Float,
    modifier: Modifier = Modifier
) {
    val infinite = rememberInfiniteTransition(label = "feed-visual")
    val phase by infinite.animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(animation = tween((980 / tempo).toInt()), repeatMode = RepeatMode.Restart),
        label = "visual-phase"
    )
    val visualEnergy by animateFloatAsState(
        targetValue = if (isPlaying) 1f else 0.16f,
        animationSpec = tween(if (isPlaying) 180 else 420),
        label = "visual-energy"
    )
    val p = if (isPlaying) phase else 0.18f
    val beat = ((kotlin.math.sin(phase * Math.PI * 2).toFloat() + 1f) / 2f) * visualEnergy
    val colors = remember(track.id) {
        listOf(track.palette.accent, FlashPlayPalette.Warm, FlashPlayPalette.Ink.copy(alpha = 0.72f))
    }
    Canvas(modifier = modifier.padding(18.dp)) {
        val center = Offset(size.width / 2f, size.height / 2f)
        when (visualIndex) {
            0, 5 -> {
                val bars = 7
                val gap = size.width / (bars + 2)
                for (i in 0 until bars) {
                    val wave = kotlin.math.sin(((p * 360f) + i * 38f) * Math.PI / 180f).toFloat()
                    val h = size.height * (0.2f + (0.18f + 0.34f * visualEnergy) * ((wave + 1f) / 2f))
                    val w = 12.dp.toPx()
                    val x = gap * (i + 1)
                    drawRoundRect(
                        color = colors[i % colors.size].copy(alpha = 0.42f + visualEnergy * 0.48f),
                        topLeft = Offset(x - w / 2f, center.y - h / 2f),
                        size = Size(w, h),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(w, w)
                    )
                }
            }
            1, 2 -> {
                for (i in 0..2) {
                    val radius = size.minDimension * (0.18f + i * 0.13f + beat * 0.1f)
                    drawCircle(
                        color = colors[i].copy(alpha = 0.12f + visualEnergy * 0.32f + i * 0.08f),
                        radius = radius,
                        center = center,
                        style = Stroke(width = (3 + 4 * visualEnergy).dp.toPx())
                    )
                }
                drawCircle(colors[1].copy(alpha = 0.7f + beat * 0.3f), radius = (18 + 9 * beat).dp.toPx(), center = center)
            }
            else -> {
                for (i in 0 until 9) {
                    val angle = ((i * 40f) + p * 360f * (0.35f + visualEnergy)) * Math.PI / 180f
                    val radius = size.minDimension * (0.12f + (i % 3) * 0.1f + beat * 0.04f)
                    val x = center.x + kotlin.math.cos(angle).toFloat() * radius
                    val y = center.y + kotlin.math.sin(angle).toFloat() * radius
                    drawCircle(
                        colors[i % colors.size].copy(alpha = 0.34f + visualEnergy * 0.52f),
                        radius = (5 + (i % 3) * 3 + beat * 4).dp.toPx(),
                        center = Offset(x, y)
                    )
                }
            }
        }
    }
}

private fun lottieAssetFor(track: MusicTrack): String {
    val assets = listOf(
