import fs from "node:fs";
import path from "node:path";

const rootDir = path.resolve(import.meta.dirname, "..");
const promptBankPath = path.join(rootDir, "android/app/src/main/assets/prompt_bank.json");
const outputDir = path.join(rootDir, "local_generated_music");
const manifestPath = path.join(outputDir, "batch_manifest.json");

const totalSongs = Number.parseInt(process.argv[2] || "20", 10);
const totalInstrumentals = Number.parseInt(process.argv[3] || "20", 10);
const endpoint = "https://api.minimax.io/v1/music_generation";
const model = "music-2.6";

function readProperties(filePath) {
  if (!fs.existsSync(filePath)) return {};
  return Object.fromEntries(
    fs
      .readFileSync(filePath, "utf8")
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter((line) => line && !line.startsWith("#") && line.includes("="))
      .map((line) => {
        const index = line.indexOf("=");
        return [line.slice(0, index).trim(), line.slice(index + 1).trim()];
      }),
  );
}

function apiKey() {
  const envKey = process.env.MINIMAX_API_KEY?.trim();
  if (envKey) return envKey;
  const localEnv = readProperties(path.join(rootDir, ".env.local")).MINIMAX_API_KEY;
  if (localEnv) return localEnv;
  const secrets = readProperties(path.join(rootDir, "android/secrets.properties")).MINIMAX_API_KEY;
  if (secrets) return secrets;
  throw new Error("MINIMAX_API_KEY is missing.");
}

function slug(value) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 64);
}

function defaultLyrics(title) {
  return `[Verse]
I carry sparks through the quiet street
Every step finds a brighter beat
If the night gets heavy on my mind
I leave a little silver line

[Chorus]
${title}, lift me into light
Turn the dark into something bright
Hold the moment, make it strong
Let my heart become the song`;
}

function readManifest() {
  if (!fs.existsSync(manifestPath)) return [];
  return JSON.parse(fs.readFileSync(manifestPath, "utf8"));
}

function writeManifest(entries) {
  fs.mkdirSync(outputDir, { recursive: true });
  fs.writeFileSync(manifestPath, JSON.stringify(entries, null, 2) + "\n");
}

async function generateOne(item, mode, index, count) {
  const isInstrumental = mode === "Instrumental";
  const body = {
    model,
    prompt: item.prompt,
    is_instrumental: isInstrumental,
    output_format: "url",
    audio_setting: {
      sample_rate: 44100,
      bitrate: 256000,
      format: "mp3",
    },
  };
  if (!isInstrumental) {
    body.lyrics = defaultLyrics(item.title);
    body.lyrics_optimizer = false;
  }

  console.log(`[${mode} ${index}/${count}] request: ${item.title}`);
  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey()}`,
    },
    body: JSON.stringify(body),
  });
  const raw = await response.text();
  if (!response.ok) {
    throw new Error(`request failed ${response.status}: ${raw}`);
  }
  const json = JSON.parse(raw);
  const baseResp = json.base_resp || {};
  if (baseResp.status_code !== 0) {
    throw new Error(`generation failed: ${baseResp.status_msg || "unknown error"}`);
  }
  const audioUrl = json.data?.audio;
  if (!audioUrl || !/^https?:\/\//.test(audioUrl)) {
    throw new Error("generation returned no audio url");
  }

  const fileName = `${String(index).padStart(2, "0")}-${mode.toLowerCase()}-${slug(item.title)}.mp3`;
  const filePath = path.join(outputDir, fileName);
  console.log(`[${mode} ${index}/${count}] download: ${fileName}`);
  const audioResponse = await fetch(audioUrl);
  if (!audioResponse.ok) {
    throw new Error(`download failed ${audioResponse.status}: ${await audioResponse.text()}`);
  }
  const bytes = Buffer.from(await audioResponse.arrayBuffer());
  fs.writeFileSync(filePath, bytes);
  console.log(`[${mode} ${index}/${count}] done: ${(bytes.length / 1024 / 1024).toFixed(2)} MB`);

  return {
    title: item.title,
    mode,
    prompt: item.prompt,
    file: path.relative(rootDir, filePath),
    bytes: bytes.length,
    durationMs: json.extra_info?.music_duration ?? null,
    generatedAt: new Date().toISOString(),
  };
}

async function main() {
  fs.mkdirSync(outputDir, { recursive: true });
  const bank = JSON.parse(fs.readFileSync(promptBankPath, "utf8"));
  const songs = bank.filter((item) => item.mode === "Song").slice(0, totalSongs);
  const instrumentals = bank.filter((item) => item.mode !== "Song").slice(0, totalInstrumentals);
  const queue = [
    ...songs.map((item, index) => ({ item, mode: "Song", index: index + 1, count: totalSongs })),
    ...instrumentals.map((item, index) => ({ item, mode: "Instrumental", index: index + 1, count: totalInstrumentals })),
  ];

  const manifest = readManifest();
  for (const task of queue) {
    const alreadyDone = manifest.find((entry) => entry.title === task.item.title && entry.mode === task.mode);
    if (alreadyDone && fs.existsSync(path.join(rootDir, alreadyDone.file))) {
      console.log(`[${task.mode} ${task.index}/${task.count}] skip existing: ${task.item.title}`);
      continue;
    }
    const entry = await generateOne(task.item, task.mode, task.index, task.count);
    manifest.push(entry);
    writeManifest(manifest);
  }

  const songCount = manifest.filter((entry) => entry.mode === "Song").length;
  const instrumentalCount = manifest.filter((entry) => entry.mode === "Instrumental").length;
  console.log(`complete: ${songCount} songs, ${instrumentalCount} instrumentals`);
  console.log(`manifest: ${path.relative(rootDir, manifestPath)}`);
}

main().catch((error) => {
  console.error(error.message);
  process.exit(1);
});

